function patchesReady(rows:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,ready:boolean,registry:readonly any[]){return!!owner&&beSpielbankStageReady1(rows,leaf,ready)&&SPEC.profiles.every(p=>{const found=rows.filter(c=>c.partId===p.partId),reg=registry.find(x=>x.number===p.number);if(found.length!==1||!reg||!Object.keys(p).every(k=>JSON.stringify(reg[k])===JSON.stringify((p as any)[k])))return false;const c=found[0],op=c.sourceFeature?.properties?.owner_shape_patch as any;return c.city===p.city&&c.objectId===p.objectId&&JSON.stringify(c.origin)===JSON.stringify(p.origin)&&nativePaintSignature(c)===p.geometrySignature&&owner(c)===p.sha256&&op?.number===p.number&&op?.sourcePartId===p.sourcePartId&&op?.geometryRole===p.geometryRole;});}
